def is_leap_year(y):
    # Gregorian rule: divisible by 4, except century years unless divisible by 400
    if y % 400 == 0:
        return True
    if y % 100 == 0:
        return False
    return y % 4 == 0


def pre(month, year):
    return 1 <= month and month <= 12 and 1 <= year and year <= 3000


def post(month, year, result):
    if month == 2:
        if is_leap_year(year):
            expected = 29
        else:
            expected = 28
    elif month == 4 or month == 6 or month == 9 or month == 11:
        expected = 30
    else:
        expected = 31
    return result == expected
